import React, { useEffect, useState } from 'react';
import { useFocusEffect } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Notifications from 'expo-notifications';
import {
  View,
  Text,
  FlatList,
  TouchableOpacity,
  StyleSheet,
  ActivityIndicator,
  Alert,
  Image,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import {
  collection,
  onSnapshot,
  query,
  orderBy,
  deleteDoc,
  doc,
  updateDoc,
} from 'firebase/firestore';
import { firestore, auth } from '../services/firebaseConfig';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import type { ListaRotasPrincipais } from '../types';
import { LinearGradient } from 'expo-linear-gradient';
import { confirmAction } from '../utils/confirmAction';

type NavigationProp = NativeStackNavigationProp<ListaRotasPrincipais, 'Escalas'>;

interface Escala {
  id: string;
  data: string;
  [key: string]: any;
}

const UIDS_PERMITIDOS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'bVpx7GAuLuTbRVWfPOT57vgO9cL2',
  // Adicione outros UIDs aqui
];

export default function TelaListaEscalas(): JSX.Element {
  const navigation = useNavigation<NavigationProp>();
  const [escalas, setEscalas] = useState<Escala[]>([]);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const uid = auth.currentUser?.uid ?? null;
    setUidAtual(uid);

    const escalasQuery = query(
      collection(firestore, 'escalas'),
      orderBy('criadoEm', 'desc')
    );

    const unsubscribe = onSnapshot(escalasQuery, (querySnapshot) => {
      const data = querySnapshot.docs.map(doc => {
        const docData = doc.data();
        let dataFormatada = '';
        if (docData.data) {
          dataFormatada = docData.data;
        } else if (docData.criadoEm?.toDate) {
          dataFormatada = docData.criadoEm.toDate().toLocaleDateString();
        }
        return {
          id: doc.id,
          data: dataFormatada,
          ...docData,
        } as Escala;
      });
      setEscalas(data);
      setLoading(false);
    }, (error) => {
      console.log('Erro ao buscar dados:', error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  // limpa flag local e badge ao entrar na tela
  useFocusEffect(
    React.useCallback(() => {
      let mounted = true;
      const limparBadge = async () => {
        try {
          // limpa contador local
          await AsyncStorage.removeItem('nova_escala');
          // limpa contador remoto (para todos)
          try {
            const metaRef = doc(firestore, 'meta', 'escalas');
            await updateDoc(metaRef, { newCount: 0, lastClearedBy: auth.currentUser?.uid ?? null, lastClearedAt: new Date() });
          } catch (err) {
            // se falhar ao atualizar remoto, não bloqueia
            console.log('Erro ao limpar contador remoto', err);
          }
          await Notifications.setBadgeCountAsync(0);
        } catch (e) {
          console.log('Erro ao limpar badge/flag', e);
        }
      };
      if (mounted) limparBadge();
      return () => { mounted = false; };
    }, [])
  );

  const excluirEscala = async (escala: Escala) => {
    if (!uidAtual || !UIDS_PERMITIDOS.includes(uidAtual)) return;
    confirmAction({
      title: 'Excluir escala',
      message: `Deseja realmente excluir a escala "${escala.data || escala.id}"? Esta ação não pode ser desfeita.`,
      onConfirm: async () => {
        try {
          await auth.currentUser?.getIdToken(true);
          await deleteDoc(doc(firestore, 'escalas', escala.id));
          setEscalas(prev => prev.filter(item => item.id !== escala.id));
        } catch (error: any) {
          console.log('Erro ao excluir escala:', error);
        }
      },
    });
  };

  const permitido = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);

  const renderItem = ({ item, index }: { item: Escala; index: number }) => {
    const cardColors = index % 3 === 0
      ? ['#27305E', '#171B36']
      : index % 3 === 1
        ? ['#2A2555', '#191D38']
        : ['#233961', '#171C37'];

    return (
    <View style={styles.escalaItem}>
      <LinearGradient
        colors={['#FFB84D', '#FF7A1A', '#46D7FF']}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.escalaGradientBorder}
      >
      <LinearGradient
        colors={cardColors}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.escalaContent}
      >
        <View style={styles.cardGlow} />
        <TouchableOpacity
          style={styles.escalaInfo}
          onPress={() => navigation.navigate('DetalhesEscala', { id: item.id })}
        >
          <Text style={styles.escalaLabel}>{item.data ? 'Data da escala' : 'Identificador'}</Text>
          <Text style={styles.escalaTexto}>{item.data || item.id}</Text>
        </TouchableOpacity>
        {permitido && (
          <TouchableOpacity
            style={styles.botaoExcluir}
            onPress={() => excluirEscala(item)}
          >
            <Text style={styles.textoBotao}>🗑️</Text>
          </TouchableOpacity>
        )}
      </LinearGradient>
      </LinearGradient>
    </View>
    );
  };

  return (
    <LinearGradient
      colors={['#0B1630', '#151936', '#241A3D']}
      style={styles.bg}
      start={{ x: 0, y: 0 }}
      end={{ x: 0, y: 1 }}
    >
      <View style={styles.container}>
        <LinearGradient
          colors={['#262A50', '#1B1F3D']}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={styles.headerBar}
        >
          <TouchableOpacity style={styles.headerBtn} onPress={() => navigation.navigate('Inicio')}>
			<Image
			  source={{ uri: 'https://img.icons8.com/?size=100&id=bIwuxbfp2H2N&format=png&color=000000.png' }}
			  style={styles.headerIcon}
			/>
		  </TouchableOpacity>
          <Text style={styles.headerTitle}>Lista de Escalas</Text>
          <TouchableOpacity style={styles.headerBtn} onPress={() => navigation.goBack()}>
			<Image
			  source={{ uri: 'https://img.icons8.com/?size=100&id=CFDbApIER33U&format=png&color=000000.png' }}
			  style={styles.headerIcon}
			/>
		  </TouchableOpacity>
        </LinearGradient>
        {loading ? (
          <ActivityIndicator size="large" color="#ff9800" style={{ marginTop: 40 }} />
        ) : (
          <FlatList
            data={escalas}
            keyExtractor={(item) => item.id}
            ListEmptyComponent={
              <Text style={styles.emptyText}>
                Nenhuma escala encontrada.
              </Text>
            }
            renderItem={renderItem}
            contentContainerStyle={styles.list}
          />
        )}

        {permitido && (
          <LinearGradient
            colors={['#FFB84D', '#FF7A1A']}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={styles.fab}
          >
            <TouchableOpacity
              style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}
              onPress={() => navigation.navigate('CriarEscala')}
            >
              <Text style={styles.fabTexto}>+</Text>
            </TouchableOpacity>
          </LinearGradient>
        )}
      </View>
    </LinearGradient>
  );
}

