import { Platform } from 'react-native';

declare global {
  interface Navigator {
    setAppBadge?: (contents?: number) => Promise<void>;
    clearAppBadge?: () => Promise<void>;
  }
}

export async function setInstalledAppBadge(count: number): Promise<void> {
  if (Platform.OS !== 'web' || typeof navigator === 'undefined') return;

  try {
    if (count > 0 && navigator.setAppBadge) {
      await navigator.setAppBadge(count);
      localStorage.setItem('worship_badge_count', String(count));
      notifyServiceWorkerBadge(count);
      return;
    }

    if (navigator.clearAppBadge) {
      await navigator.clearAppBadge();
    }
    localStorage.setItem('worship_badge_count', '0');
    notifyServiceWorkerBadge(0);
  } catch (error) {
    console.log('Nao foi possivel atualizar o badge do PWA:', error);
  }
}

function notifyServiceWorkerBadge(count: number) {
  if (typeof navigator === 'undefined' || !navigator.serviceWorker?.controller) return;

  navigator.serviceWorker.controller.postMessage({
    type: 'SET_BADGE_COUNT',
    count,
  });
}
