import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  TouchableOpacity,
  TextInput,
  Alert,
  Modal,
  Platform,
  KeyboardAvoidingView,
} from 'react-native';
import { getFirestore, collection, getDocs, addDoc, deleteDoc, doc, Timestamp, orderBy, query } from 'firebase/firestore';
import { MaterialIcons, MaterialCommunityIcons } from '@expo/vector-icons';
import { getAuth } from 'firebase/auth';
import { useNavigation } from '@react-navigation/native';
import { LinearGradient } from 'expo-linear-gradient';
import { confirmAction } from '../utils/confirmAction';

const db = getFirestore();

const IUDS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'bVpx7GAuLuTbRVWfPOT57vgO9cL2',
];

type Agendamento = {
  id?: string;
  titulo: string;
  data: string;
  descricao?: string;
  criadoEm?: any;
};

const cardGradients = [
  ['#151C3C', '#222047', '#2D2146'],
  ['#111D34', '#1F2948', '#243657'],
  ['#211B3D', '#24254A', '#18364A'],
];

function formatarDataInput(text: string) {
  let cleaned = text.replace(/\D/g, '');
  let formatted = '';
  if (cleaned.length > 4) {
    formatted = cleaned.replace(/^(\d{2})(\d{2})(\d{0,4}).*/, '$1/$2/$3');
  } else if (cleaned.length > 2) {
    formatted = cleaned.replace(/^(\d{2})(\d{0,2})/, '$1/$2');
  } else {
    formatted = cleaned;
  }
  return formatted;
}

function GradientButton({ children, onPress, variant = 'primary', style }: any) {
  const colors = variant === 'secondary'
    ? ['#67E8F9', '#38BDF8']
    : ['#FFB84D', '#FF7A3D'];

  return (
    <TouchableOpacity onPress={onPress} activeOpacity={0.86} style={[styles.buttonWrap, style]}>
      <LinearGradient colors={colors} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.gradientButton}>
        {children}
      </LinearGradient>
    </TouchableOpacity>
  );
}

export default function TelaAgenda() {
  const [agendamentos, setAgendamentos] = useState<Agendamento[]>([]);
  const [novoTitulo, setNovoTitulo] = useState('');
  const [novaData, setNovaData] = useState('');
  const [novaDescricao, setNovaDescricao] = useState('');
  const [modalVisible, setModalVisible] = useState(false);
  const [uidAtual, setUidAtual] = useState<string | null>(null);

  const navigation = useNavigation();

  useEffect(() => {
    setUidAtual(getAuth().currentUser?.uid ?? null);
    buscarAgendamentos();
  }, []);

  async function buscarAgendamentos() {
    try {
      const q = query(collection(db, 'agendas'), orderBy('data'));
      const snap = await getDocs(q);
      const lista: Agendamento[] = [];
      snap.forEach(docSnap => {
        lista.push({ id: docSnap.id, ...docSnap.data() } as Agendamento);
      });
      setAgendamentos(lista);
    } catch (e) {
      Alert.alert('Erro', 'Não foi possível carregar os agendamentos.');
    }
  }

  async function adicionarAgendamento() {
    const dataFormatada = novaData;
    if (!novoTitulo || !dataFormatada.match(/^\d{2}\/\d{2}\/\d{4}$/)) {
      Alert.alert('Preencha corretamente o título e a data (dd/mm/aaaa)');
      return;
    }
    try {
      await addDoc(collection(db, 'agendas'), {
        titulo: novoTitulo,
        data: dataFormatada,
        descricao: novaDescricao,
        criadoEm: Timestamp.now(),
      });
      setNovoTitulo('');
      setNovaData('');
      setNovaDescricao('');
      setModalVisible(false);
      buscarAgendamentos();
    } catch (e) {
      Alert.alert('Erro', 'Não foi possível adicionar.');
    }
  }

  const excluirAgendamento = async (id: string | undefined) => {
    if (!id || !uidAtual || !IUDS.includes(uidAtual)) return;
    confirmAction({
      title: 'Excluir agendamento',
      message: 'Tem certeza que deseja excluir este agendamento?',
      onConfirm: async () => {
        try {
          await getAuth().currentUser?.getIdToken(true);
          await deleteDoc(doc(db, 'agendas', id));
          setAgendamentos(prev => prev.filter(ag => ag.id !== id));
        } catch (error: any) {
          console.log('Erro ao excluir agendamento:', error);
        }
      },
    });
  };

  const permitido = !!uidAtual && IUDS.includes(uidAtual);

  const renderItem = ({ item, index }: { item: Agendamento; index: number }) => (
    <LinearGradient
      colors={['#FFB84D', '#43E97B', '#46D7FF']}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
      style={styles.cardBorder}
    >
      <LinearGradient
        colors={cardGradients[index % cardGradients.length]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.card}
      >
        <View style={styles.cardGlow} />
        <View style={styles.cardHeader}>
          <View style={styles.cardIconCircle}>
            <MaterialCommunityIcons name="calendar-star" size={24} color="#111827" />
          </View>
          <View style={{ flex: 1, minWidth: 0 }}>
            <Text style={styles.cardTitulo} numberOfLines={2}>{item.titulo}</Text>
            <View style={styles.dateChip}>
              <MaterialIcons name="event" size={15} color="#67E8F9" />
              <Text style={styles.cardData}>{item.data}</Text>
            </View>
          </View>
          {permitido && (
            <TouchableOpacity onPress={() => excluirAgendamento(item.id)} style={styles.botaoExcluir} activeOpacity={0.8}>
              <MaterialIcons name="delete-outline" size={20} color="#FFE5E5" />
            </TouchableOpacity>
          )}
        </View>

        {item.descricao ? (
          <View style={styles.cardDescricaoBox}>
            <MaterialIcons name="notes" size={18} color="#FFB84D" />
            <Text style={styles.cardDescricao}>{item.descricao}</Text>
          </View>
        ) : null}
      </LinearGradient>
    </LinearGradient>
  );

  return (
    <LinearGradient colors={['#0B1630', '#161934', '#241A3D']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.bg}>
      <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
        <FlatList
          data={agendamentos}
          keyExtractor={item => item.id || item.titulo + item.data}
          renderItem={renderItem}
          style={styles.list}
          contentContainerStyle={styles.scroll}
          keyboardShouldPersistTaps="handled"
          ListHeaderComponent={
            <>
              <View style={styles.header}>
                <TouchableOpacity style={styles.headerBotao} onPress={() => navigation.navigate('Inicio' as never)} activeOpacity={0.85}>
                  <MaterialCommunityIcons name="home-variant-outline" size={24} color="#43E97B" />
                </TouchableOpacity>
                <View style={styles.headerTitleWrap}>
                  <View style={styles.headerTitleIcon}>
                    <MaterialCommunityIcons name="calendar-month" size={23} color="#111827" />
                  </View>
                  <Text style={styles.headerTitulo}>Agenda</Text>
                </View>
                <TouchableOpacity style={styles.headerBotao} onPress={() => navigation.goBack()} activeOpacity={0.85}>
                  <MaterialIcons name="keyboard-backspace" size={25} color="#46D7FF" />
                </TouchableOpacity>
              </View>

              <View style={styles.hero}>
                <Text style={styles.heroTitle}>Agenda de Compromissos</Text>
                <Text style={styles.heroSubtitle}>{agendamentos.length} compromisso{agendamentos.length === 1 ? '' : 's'} cadastrado{agendamentos.length === 1 ? '' : 's'}</Text>
              </View>

              {permitido && (
                <GradientButton style={styles.novoBtn} onPress={() => setModalVisible(true)}>
                  <MaterialIcons name="add-circle-outline" size={22} color="#111827" />
                  <Text style={styles.gradientButtonText}>Novo Agendamento</Text>
                </GradientButton>
              )}
            </>
          }
          ListEmptyComponent={
            <View style={styles.emptyBox}>
              <MaterialCommunityIcons name="calendar-remove" size={48} color="#67E8F9" />
              <Text style={styles.emptyText}>Nenhum agendamento cadastrado.</Text>
            </View>
          }
        />

        <Modal visible={modalVisible} animationType="fade" transparent onRequestClose={() => setModalVisible(false)}>
          <View style={styles.modalBg}>
            <LinearGradient colors={['#FFB84D', '#43E97B', '#46D7FF']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.modalBorder}>
              <LinearGradient colors={['#252B55', '#171B38']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.modalBox}>
                <Text style={styles.modalTitulo}>Novo Agendamento</Text>
                <View style={styles.inputBox}>
                  <MaterialIcons name="title" size={20} color="#FFB84D" />
                  <TextInput style={styles.input} placeholder="Título" value={novoTitulo} onChangeText={setNovoTitulo} placeholderTextColor="#BFD7FF" />
                </View>
                <View style={styles.inputBox}>
                  <MaterialIcons name="calendar-today" size={20} color="#67E8F9" />
                  <TextInput style={styles.input} placeholder="Data" value={novaData} onChangeText={text => setNovaData(formatarDataInput(text))} placeholderTextColor="#BFD7FF" keyboardType="numeric" maxLength={10} />
                </View>
                <View style={styles.inputBox}>
                  <MaterialIcons name="description" size={20} color="#72F2A4" />
                  <TextInput style={[styles.input, styles.textArea]} placeholder="Descrição (opcional)" value={novaDescricao} onChangeText={setNovaDescricao} placeholderTextColor="#BFD7FF" multiline />
                </View>
                <View style={styles.modalActions}>
                  <GradientButton style={{ flex: 1, marginRight: 8 }} onPress={() => setModalVisible(false)} variant="secondary">
                    <Text style={styles.gradientButtonText}>Cancelar</Text>
                  </GradientButton>
                  <GradientButton style={{ flex: 1, marginLeft: 8 }} onPress={adicionarAgendamento}>
                    <Text style={styles.gradientButtonText}>Salvar</Text>
                  </GradientButton>
                </View>
              </LinearGradient>
            </LinearGradient>
          </View>
        </Modal>
      </KeyboardAvoidingView>
    </LinearGradient>
  );
}

